    def char(c):
        def parse(s, pos):
            if pos < len(s) and s[pos] == c:
                return (c, pos + 1)
            return None
        return parse

    def satisfy(pred, name="char"):
        """Match any character satisfying pred."""
        def parse(s, pos):
            if pos < len(s) and pred(s[pos]):
                return (s[pos], pos + 1)
            return None
        return parse

    def regex(pattern, flags=0):
        """Match a regex anchored at the current position."""
        rx = re.compile(pattern, flags)
        def parse(s, pos):
            m = rx.match(s, pos)
            if m:
                return (m.group(0), m.end())
            return None
        return parse

    def lit(string):
        """Match a literal string."""
        n = len(string)
        def parse(s, pos):
            if s[pos:pos+n] == string:
                return (string, pos + n)
            return None
        return parse

    def eof():
        """Match the end of input."""
        def parse(s, pos):
            return (None, pos) if pos == len(s) else None
        return parse

    # Quick tests
